{
  "promos": [
    {
      "title": "She Bled to Free Him",
      "start_block": "B004",
      "end_block": "B024",
      "hook": "Juliana steps from the briar patch, cloak torn and cheeks scratched, holding out the emerald ring with blood-streaked hands as she says, 'I found it.'",
      "cliffhanger": "Alexander scoops Juliana into his arms and says, 'You should never have had to bleed for me,' leaving the weight of her sacrifice hanging.",
      "why": "Opens on the aftermath of her brutal ordeal, shows the cost of her loyalty, and ends on his guilt and devotion before any resolution.",
      "context_gap": "Why she had to retrieve the ring from thorns and who the constable is."
    },
    {
      "title": "His Vow of Vengeance",
      "start_block": "B028",
      "end_block": "B051",
      "hook": "Alexander kneels before Juliana by the fire, wrapping her torn hands as he says, 'You could have lost your hands.'",
      "cliffhanger": "Alexander's scarred knuckles clench into an iron fist beside the bloody bucket as an ominous bass boom cuts to black.",
      "why": "Builds from intimate tenderness to a dark promise of revenge, ending on the episode's final unresolved threat.",
      "context_gap": "Who hurt Juliana and why Alexander feels responsible."
    },
    {
      "title": "Bloodied Hands, Unbroken Love",
      "start_block": "B014",
      "end_block": "B039",
      "hook": "Alexander's trembling hands grasp Juliana's bloodied, lacerated fingers as he gasps, 'What have they done to you?'",
      "cliffhanger": "Juliana smiles through tears and says, 'You didn't hurt me,' leaving his guilt and her forgiveness unresolved.",
      "why": "Starts on the shocking sight of her wounds, centers on their emotional bond, and cuts before he fully accepts her reassurance.",
      "context_gap": "The identity of 'they' and the events that led to her injuries."
    }
  ],
  "moments": [
    {
      "start_block": "B004",
      "end_block": "B007",
      "kind": "hook",
      "description": "Juliana emerges from the thorns holding the emerald ring and commands the constable to release her husband."
    },
    {
      "start_block": "B014",
      "end_block": "B017",
      "kind": "emotional",
      "description": "Alexander turns Juliana's bloodied hands over and asks in a trembling voice what they have done to her."
    },
    {
      "start_block": "B032",
      "end_block": "B034",
      "kind": "emotional",
      "description": "Alexander says she could have lost her hands, and Juliana whispers that she didn't lose him."
    },
    {
      "start_block": "B047",
      "end_block": "B051",
      "kind": "cliffhanger",
      "description": "Alexander vows no one will hurt her again, then clenches his fist beside the bloody bucket as the screen cuts to black."
    }
  ]
}
